import{subscribeLanguage,translateUi}from './i18n.js';
import{teamLeaf,teamAttr}from './team-ui.js';
import{teamPreviewVerified,onTeamPreviewChange}from './team-preview-access.js';
const tabs={schedule:teamLeaf('schedule'),students:teamLeaf('students'),homework:teamLeaf('homework')};
const sample={schedule:'<h2>'+teamLeaf('nextLesson')+'</h2><p class="knowledge-eyebrow">'+teamLeaf('tajweedExample')+'</p><h3>'+teamLeaf('vowels')+'</h3><p>'+teamLeaf('groupDescription')+'</p><button class="button" type="button" data-demo-lesson>'+teamLeaf('viewLesson')+'</button>',students:'<h2>'+teamLeaf('studyGroup')+'</h2><p>'+teamLeaf('exampleStudents')+'</p>'+[teamLeaf('studentOne'),teamLeaf('studentTwo'),teamLeaf('studentThree')].map((name,i)=>'<article class="team-demo-student"><span class="team-demo-avatar">'+(i+1)+'</span><span><strong>'+name+'</strong><small>'+teamLeaf('reviewVowels')+'</small></span><span class="team-demo-progress">'+[75,50,25][i]+'%</span></article>').join(''),homework:'<h2>'+teamLeaf('reviewAssignment')+'</h2><p>'+teamLeaf('assignmentDescription')+'</p><button class="button secondary" type="button" data-demo-feedback>'+teamLeaf('showFeedback')+'</button><p class="team-demo-feedback" hidden>'+teamLeaf('sampleFeedback')+'</p>'};
let active=null;
export function stopTeamLearningDemo(){if(!active)return;active.off?.();active.stopLocale?.();active.root.remove();active=null;}
export function mountTeamLearningDemo(host,feature){
 if(!teamPreviewVerified()||!['teacher-preview','online-lessons'].includes(feature))return false;
 if(active?.host===host&&active.feature===feature&&active.root.isConnected)return true;
 stopTeamLearningDemo();const root=document.createElement('section');root.className='owner-learning-shell team-learning-demo';
 const teacher=feature==='teacher-preview';let tab='schedule';
 root.innerHTML='<a class="alphabet-back" href="#knowledge">'+teamLeaf('backKnowledge')+'</a><div class="page-head"><div><span class="knowledge-eyebrow">'+teamLeaf('example')+'</span><h1 tabindex="-1">'+teamLeaf(teacher?'teacherCabinet':'onlineLessons')+'</h1><p>'+teamLeaf('exploreExample')+'</p></div></div>'+(teacher?'<div class="team-demo-tabs" role="tablist" '+teamAttr('teacherCabinet',{},'aria-label')+'>'+Object.entries(tabs).map(([id,label])=>'<button class="button secondary" type="button" role="tab" id="team-demo-tab-'+id+'" aria-controls="team-demo-panel" data-demo-tab="'+id+'">'+label+'</button>').join('')+'</div><section id="team-demo-panel" class="panel section" role="tabpanel"></section>':'<section class="team-demo-classroom"><div class="team-demo-video"><span class="team-demo-avatar">S</span><strong>'+teamLeaf('teacher')+'</strong><small>'+teamLeaf('lessonScreen')+'</small></div><div class="team-demo-material"><span class="knowledge-eyebrow">'+teamLeaf('reviewVowelsUpper')+'</span><p lang="ar" dir="rtl">بَ بِ بُ</p><span>'+teamLeaf('vowelNames')+'</span></div><div class="team-demo-lesson-tools"><span>'+teamLeaf('microphone')+'</span><span>'+teamLeaf('video')+'</span><span>'+teamLeaf('showMaterial')+'</span></div><p>'+teamLeaf('lessonLayout')+'</p><a class="button secondary" href="#knowledge?view=teacher-preview">'+teamLeaf('viewTeacher')+'</a></section>');
 const draw=()=>{if(!teacher)return;root.querySelector('#team-demo-panel').innerHTML=sample[tab];root.querySelector('#team-demo-panel').setAttribute('aria-labelledby','team-demo-tab-'+tab);for(const button of root.querySelectorAll('[data-demo-tab]')){button.setAttribute('aria-selected',String(button.dataset.demoTab===tab));button.tabIndex=button.dataset.demoTab===tab?0:-1;}translateUi(root);};
 root.onclick=event=>{if(!teamPreviewVerified())return;const button=event.target.closest('button');if(button?.dataset.demoTab){tab=button.dataset.demoTab;draw();}else if(button?.hasAttribute('data-demo-lesson'))location.hash='knowledge?view=online-lessons';else if(button?.hasAttribute('data-demo-feedback')){const feedback=root.querySelector('.team-demo-feedback');feedback.hidden=!feedback.hidden;button.setAttribute('aria-expanded',String(!feedback.hidden));}};
 root.onkeydown=event=>{const button=event.target.closest('[data-demo-tab]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const ids=Object.keys(tabs),i=ids.indexOf(tab);tab=event.key==='Home'?ids[0]:event.key==='End'?ids.at(-1):ids[(i+(event.key==='ArrowRight'?1:ids.length-1))%ids.length];draw();root.querySelector('[data-demo-tab="'+tab+'"]').focus();};
 host.replaceChildren(root);draw();translateUi(root);active={host,root,feature,stopLocale:subscribeLanguage(()=>translateUi(root)),off:onTeamPreviewChange(()=>{if(!teamPreviewVerified())stopTeamLearningDemo();})};return true;
}
